module top;
  integer n, i, r;
  reg [3:0] count;
  initial begin
    r = $fscanf(32'h8000_0000, "%d", n);
    if (r == 1) begin
      count = 0;
      for (i = 0; i < n; i = i + 1) begin
        $display("%0d", count);
        count = count + 1;
      end
    end
    $finish;
  end
endmodule
